    ids.add(s["id"])
    s = {k: v for k, v in s.items() if v is not None or k == "nominationBody"}
    r = {k: s[k] for k in ORDER if k in s}
    assert set(r) == set(s), (s["id"], set(s) - set(r))
    data.append(r); added += 1

